#define CHECK(c) Check((c) ? true : false, __LINE__)

struct _Rb_tree_node_base {
    bool                _M_color;
    _Rb_tree_node_base* _M_parent;
    _Rb_tree_node_base* _M_left;
    _Rb_tree_node_base* _M_right;
};
struct CPersistedDeadEntity {              // NThingManager::CEntityRuntimePersistence
    u64           UID;
    bool          GamePersistent;
    unsigned long SectionNameCRC;
};
struct SValue {                            // pair<const unsigned __int64, CPersistedDeadEntity>
    u64                  first;
    CPersistedDeadEntity second;
};
static SValue MakeValue(int k)
{
    SValue v;
    v.first = (u64)k << 32 | (u64)k;
    v.second.UID = v.first;
    v.second.GamePersistent = (k & 1) != 0;
    v.second.SectionNameCRC = 0x1000u + k;
    return v;
}
static int KeyOf(const SValue& v) { return (int)(v.first >> 32); }
static bool ExtraOk(const SValue& v, int k)
{
    return v.second.UID == v.first && v.second.GamePersistent == ((k & 1) != 0) && v.second.SectionNameCRC == 0x1000u + k;
}
struct SNode : _Rb_tree_node_base {
    SValue _M_value_field;
};

