        tmp->_M_value_field = v;
        return tmp;
    }
    iterator _M_insert(_Rb_tree_node_base* x_, _Rb_tree_node_base* y_, const SValue& v, _Rb_tree_node_base* w_)
    {
        SNode* w = (SNode*)w_;
        SNode* y = (SNode*)y_;
        SNode* x = (SNode*)x_;
