static void RunTest()
{
    _Rb_tree_node_base header;
    header._M_color = false;
    header._M_parent = 0;
    header._M_left = &header;
    header._M_right = &header;
    CTree t;
    t._M_header = &header;
    t._M_node_count = 0;

