    SNode* n1 = (SNode*)t._M_insert(0, &header, MakeValue(50), 0)._M_node;
    CHECK(header._M_parent == n1 && header._M_left == n1 && header._M_right == n1);
    CHECK(n1->_M_parent == &header && n1->_M_left == 0 && n1->_M_right == 0);
