    CHECK(n2->_M_right == n5 && n2->_M_left == 0 && header._M_left == n2);
    CHECK(KeyOf(n5->_M_value_field) == 10 && ExtraOk(n5->_M_value_field, 10));
    CHECK(t._M_node_count == 5 && g_rebalanceCalls == 5 && g_rebalanceNode == n5);

